EVENTS = [
 ("industrial", 1870, 0, 0, "08-09", "The Education Act", "Y Ddeddf Addysg",
  "The Elementary Education Act sets up school boards to put a school within reach of every child in England and Wales. It says nothing about Welsh: lessons, books and tests are in English.",
  "Mae’r Ddeddf Addysg Elfennol yn sefydlu byrddau ysgol i roi ysgol o fewn cyrraedd pob plentyn yng Nghymru a Lloegr. Nid yw’n dweud gair am y Gymraeg: Saesneg yw’r gwersi, y llyfrau a’r profion.", 0, "", "Elementary_Education_Act_1870"),
 ("industrial", 1885, 0, 0, "", "A society for Welsh in the schools", "Cymdeithas i’r Gymraeg yn yr ysgolion",
  "At the National Eisteddfod in Aberdare, Dan Isaac Davies and his friends found the Society for the Utilisation of the Welsh Language, to bring Welsh into the schools. Within a year Welsh can earn a school a grant.",
  "Yn Eisteddfod Genedlaethol Aberdâr mae Dan Isaac Davies a’i gyfeillion yn sefydlu cymdeithas i ddod â’r Gymraeg i’r ysgolion. O fewn blwyddyn gall y Gymraeg ennill grant i ysgol.", 0, "", "Dan_Isaac_Davies"),
]
